package cn.workbench;
import org.springframework.stereotype.Component;import jakarta.servlet.http.HttpServletRequest;import java.util.*;
@Component public class Policy {
 final Store db;final Records records;final OrganizationChanges changes;final TestAccessPolicy testAccess;public Policy(Store db,Records r,OrganizationChanges changes,TestAccessPolicy testAccess){this.db=db;records=r;this.changes=changes;this.testAccess=testAccess;}
 public record Actor(long uid,String role,Integer company,Integer dept,long scopeId,Long delegationId,Long delegatorId,Set<String> delegationPermissions){public Actor(long uid,String role,Integer company,Integer dept,long scopeId){this(uid,role,company,dept,scopeId,null,null,Set.of());}public boolean allows(String permission){return delegationId==null||delegationPermissions.contains(permission);}public boolean leader(){return Set.of("GROUP_LEADER","DIVISION_LEADER","COMPANY_LEADER").contains(role);}public boolean departmentHead(){return role.equals("DEPT_HEAD");}public boolean administrator(){return role.equals("ADMIN");}public boolean globalAdmin(){return administrator()&&company==null;}}
 public Actor actor(HttpServletRequest q){long uid=Auth.uid(q);var id=q.getSession().getAttribute("scopeId");if(id==null)throw ApiException.denied();var s=db.scope(uid,Jsons.number(id));if(s==null)throw ApiException.denied();return changes.actor(q,new Actor(uid,(String)s.get("role"),s.get("companyId")==null?null:Jsons.integer(s.get("companyId")),s.get("deptId")==null?null:Jsons.integer(s.get("deptId")),Jsons.number(id)));}
 public void company(Actor a,int company){if(!Domain.companyAllowed(a.role(),a.company(),company))throw ApiException.denied();}
 public void taskLeader(Actor a,int company){if(a.globalAdmin())return;leader(a,company);}
 public void leader(Actor a,int company){company(a,company);if(!a.leader())throw ApiException.denied();}
 public void infrastructureCompany(Actor a,int company){if(a.administrator()&&a.company()==null)return;company(a,company);}
 public void admin(Actor a){if(!a.administrator())throw ApiException.denied();}
 public boolean canSeeTask(Actor a,Map<String,Object> t){if(a.administrator())return a.globalAdmin();int company=Jsons.integer(t.get("companyId"));if(a.leader()&&Domain.companyAllowed(a.role(),a.company(),company))return true;if("DRAFT".equals(t.get("status")))return false;long id=Jsons.number(t.get("id"));for(var s:records.children(id,"SUB_TASK"))if(Objects.equals(a.company(),Jsons.integer(s.get("companyId")))&&(a.leader()||Objects.equals(a.dept(),Jsons.integer(s.get("deptId")))&&(a.departmentHead()||Objects.equals(a.uid(),s.get("ownerId")==null?null:Jsons.number(s.get("ownerId")))||db.assignees(Jsons.number(s.get("id"))).contains(a.uid()))))return true;return false;}
 public Map<String,Object> task(Actor a,long id){var t=records.get(id);if(!"TASK".equals(t.get("kind"))||!canSeeTask(a,t))throw ApiException.denied();return t;}
 public void subtask(Actor a,Map<String,Object> s,boolean mutate){if(!"SUB_TASK".equals(s.get("kind")))throw ApiException.denied();company(a,Jsons.integer(s.get("companyId")));if(!a.leader()&&"DRAFT".equals(records.get(Jsons.number(s.get("taskId"))).get("status")))throw ApiException.denied();if(a.leader()&&!mutate)return;if(!Objects.equals(a.dept(),Jsons.integer(s.get("deptId"))))throw ApiException.denied();if(!a.departmentHead()&&!Objects.equals(a.uid(),s.get("ownerId")==null?null:Jsons.number(s.get("ownerId")))&&!db.assignees(Jsons.number(s.get("id"))).contains(a.uid()))throw ApiException.denied();}
 public boolean canSeeAttachment(Actor a,Map<String,Object> attachment,Map<String,Object> task){if(!canSeeTask(a,task))return false;if(a.globalAdmin()||a.leader()&&Domain.companyAllowed(a.role(),a.company(),Jsons.integer(task.get("companyId"))))return true;if(a.departmentHead()&&Objects.equals(a.company(),Jsons.integer(task.get("companyId")))&&Objects.equals(a.dept(),Jsons.integer(task.get("hostDeptId"))))return true;if(attachment.get("subTaskId")!=null){try{subtask(a,records.get(Jsons.number(attachment.get("subTaskId"))),false);return true;}catch(ApiException denied){return false;}}if(attachment.get("deptId")==null&&Objects.equals(Jsons.integer(attachment.get("companyId")),Jsons.integer(task.get("companyId"))))return true;return Objects.equals(a.company(),Jsons.integer(attachment.get("companyId")))&&(a.leader()||Objects.equals(a.dept(),attachment.get("deptId")==null?null:Jsons.integer(attachment.get("deptId"))));}
 public void freshTotp(HttpServletRequest q){if(testAccess.allows(Auth.uid(q)))return;Object at=q.getSession().getAttribute("totpAt");if(at==null||System.currentTimeMillis()-Jsons.number(at)>5*60*1000)throw new ApiException(403,"FRESH_TOTP_REQUIRED","请在五分钟内完成二次验证");}
}
